/**
 * Generates the app icon set from code so the brand mark can never drift between
 * the favicon, the manifest, the Apple touch icon and the OG cover.
 *
 * Output (all committed, all regenerated by `npm run build`):
 *   public/icon-192.png, public/icon-512.png, public/icon-512-maskable.png,
 *   public/apple-touch-icon.png (180), public/favicon.ico (32, PNG payload)
 */
import { createCanvas } from '@napi-rs/canvas';
import { mkdirSync, writeFileSync } from 'node:fs';

const PURPLE_FROM = '#7C5CFA';
const PURPLE_TO = '#5B2FD1';

function drawMark(size, { padding = 0, rounded = true } = {}) {
  const canvas = createCanvas(size, size);
  const ctx = canvas.getContext('2d');

  const gradient = ctx.createLinearGradient(0, 0, size, size);
  gradient.addColorStop(0, PURPLE_FROM);
  gradient.addColorStop(1, PURPLE_TO);

  // Full-bleed background for the maskable variant, rounded for the rest.
  ctx.fillStyle = gradient;
  if (rounded && padding === 0) {
    const r = size * 0.22;
    ctx.beginPath();
    ctx.moveTo(r, 0);
    ctx.arcTo(size, 0, size, size, r);
    ctx.arcTo(size, size, 0, size, r);
    ctx.arcTo(0, size, 0, 0, r);
    ctx.arcTo(0, 0, size, 0, r);
    ctx.closePath();
    ctx.fill();
  } else {
    ctx.fillRect(0, 0, size, size);
  }

  // Glyph: a chunky white "N" drawn as geometry, so the mark never depends on a
  // font being installed on the build machine. The stems and the crossbar are
  // separate sub-paths filled together, giving a clean union.
  const inner = size - padding * 2;
  const o = padding;
  const x0 = o + inner * 0.26;
  const x1 = o + inner * 0.74;
  const y0 = o + inner * 0.27;
  const y1 = o + inner * 0.73;
  const w = inner * 0.15;
  const r = w * 0.34;

  ctx.fillStyle = '#ffffff';
  ctx.beginPath();
  ctx.roundRect(x0, y0, w, y1 - y0, r);
  ctx.roundRect(x1 - w, y0, w, y1 - y0, r);
  ctx.fill();

  ctx.beginPath();
  ctx.moveTo(x0 + w * 0.5, y0);
  ctx.lineTo(x0 + w * 1.5, y0);
  ctx.lineTo(x1 - w * 0.5, y1);
  ctx.lineTo(x1 - w * 1.5, y1);
  ctx.closePath();
  ctx.fill();

  return canvas;
}

/** Minimal ICO container holding a single PNG frame (valid for every modern browser). */
function pngToIco(png) {
  const header = Buffer.alloc(6);
  header.writeUInt16LE(0, 0); // reserved
  header.writeUInt16LE(1, 2); // type: icon
  header.writeUInt16LE(1, 4); // frame count
  const entry = Buffer.alloc(16);
  entry[0] = 32; // width
  entry[1] = 32; // height
  entry[2] = 0; // palette
  entry[3] = 0; // reserved
  entry.writeUInt16LE(1, 4); // colour planes
  entry.writeUInt16LE(32, 6); // bits per pixel
  entry.writeUInt32LE(png.length, 8);
  entry.writeUInt32LE(header.length + entry.length, 12);
  return Buffer.concat([header, entry, png]);
}

mkdirSync('public', { recursive: true });

const outputs = [
  ['public/icon-192.png', drawMark(192), 192],
  ['public/icon-512.png', drawMark(512), 512],
  // Maskable icons need the glyph inside the 80% safe zone: pad and full-bleed.
  ['public/icon-512-maskable.png', drawMark(512, { padding: 64, rounded: false }), 512],
  ['public/apple-touch-icon.png', drawMark(180, { rounded: false }), 180],
];

for (const [file, canvas] of outputs) {
  writeFileSync(file, canvas.toBuffer('image/png'));
}
writeFileSync('public/favicon.ico', pngToIco(drawMark(32).toBuffer('image/png')));

console.log(`Generated ${outputs.length} PNG icons and favicon.ico`);
